// Typed access to the engine catalog (generated by core/export_catalog.py).
// Market availability is derived here from the one rule the engine enforces:
// an indicator is available iff its inputs ⊆ the market's provided columns.
import raw from "./catalog.json";

export interface Param {
  name: string;
  type: string;
  default: number | string | null;
  min: number | null;
  max: number | null;
}
export interface Indicator {
  id: string;
  label: string;
  category: string;
  inputs: string[];
  params: Param[];
}
export interface Market {
  id: string;
  label: string;
  provides: string[];
  series_kind: string;
  asset_class: string;
}

export const INDICATORS = raw.indicators as unknown as Indicator[];
export const MARKETS = raw.markets as unknown as Market[];
export const COUNTS = raw.counts as { indicators: number; markets: number };

export function isAvailable(ind: Indicator, market: Market): boolean {
  return ind.inputs.every((c) => market.provides.includes(c));
}

export function missingCols(ind: Indicator, market: Market): string[] {
  return ind.inputs.filter((c) => !market.provides.includes(c));
}
